def unit_of_work(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        timeout = kwargs.get("timeout")
        if timeout is not None:
            # Validate the timeout value
            if timeout < 0:
                raise ValueError("The timeout value cannot be negative.")
            elif timeout == 0:
                # A zero duration will make the transaction execute indefinitely
                return func(*args, **kwargs)
            else:
                # Apply the timeout to the transaction
                with timeout(seconds=timeout):
                    return func(*args, **kwargs)
        else:
            # Use the default timeout configured in the database
            return func(*args, **kwargs)
    return wrapper

