def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    ids = os.environ.get("language", "en")
    if not ids:
        raise RuntimeError("Unknown language ID. Please specify a language ID using the environment variable 'language'.")
    random.seed(ids)
    return random.sample(seq, len(seq))

