def parse_version(s: str) -> Tuple[int, ...]:
    """
    Extracts major, minor, and patch versions from the given string representation of a version number.
    The function raises a ValueError if the input string does not match the basic version format.
    """
    match = re.match(r'(\d+)\.(\d+)\.(\d+)', s)
    if not match:
        raise ValueError(f'{s} is not a valid version number.')
    return int(match.group(1)), int(match.group(2)), int(match.group(3))

