def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    bases = []
    for cls in classes:
        if cls not in bases:
            bases.append(cls)
            for other in bases:
                if issubclass(cls, other):
                    bases.remove(other)
                    continue
    return bases

