def integral(bins, edges):
        area = 0
        for i in range(len(bins)):
            if i == 0:
                area += bins[i] * edges[i]
            elif i < len(bins):
                area += bins[i] * edges[i] - bins[i-1] * edges[i-1]
            elif i == len(bins):
                area += bins[i] * edges[i]
            else:
                raise ValueError("Unexpected error. Invalid edges/bins input.")

        return area

