def pretty(self, indent=0, debug=False):
        """Return a pretty formatted representation of self."""

        if isinstance(indent, int):
            whitespace = " " * indent
        elif isinstance(indent, str):
            whitespace = indent
        else:
            raise TypeError("'indent' must be an integer or a string")

        if debug:
            return self.debug()

        output = ""
        if isinstance(self, TextContent):
            output += whitespace + "<" + self.getname() + ">"
            output += whitespace + self.text + "</" + self.getname() + ">"
        elif isinstance(self, AbstractElement):
            output += whitespace
            output += self.open_tag + ">"
            for child in self:
                output += child.pretty(indent + 1)
            output += whitespace + self.close_tag
        elif isinstance(self, structural_element):
            output += whitespace + self.open_tag + ">"
            for child in self:
                output += child.pretty(indent + 1)
            output += whitespace + self.close_tag
        elif isinstance(self, annotated_element):
            output += whitespace + self.open_tag
            for attrib in self.getattribs():
                output += whitespace + " " + attrib.name + "=\"" + attrib.value + "\""
            for child in self:
                output += child.pretty(indent + 1)
            output += whitespace + self.close_tag

        return output

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if isinstance(arg, str):
            LHS = arg.split('&')
            for i in range(len(LHS)):
                for j in range(i+1, len(LHS)):
                    x = LHS[i]
                    y = LHS[j]
                    if x in y:
                        # return the other terms
                        new_args.extend(set(LHS) - set([x]))
                        break
                if len(new_args) > 0:
                    break
            else:
                new_args.append(arg)
        elif isinstance(arg, tuple):
            # convert tuple to list
            LHS = list(arg)
            for i in range(len(LHS)):
                for j in range(i+1, len(LHS)):
                    x = LHS[i]
                    y = LHS[j]
                    if x in y:
                        # return the other terms
                        new_args.extend(set(LHS) - set([x]))
                        break
                if len(new_args) > 0:
                    break
            else:
                new_args.append(arg)
        else:
            new_args.append(arg)
    return new_args

def absorb(self, args):
    new_args = []
    for arg in args:
        if arg.is_atomic():
            new_args.append(arg)
        else:
            new_args += self.absorb(arg.get_argument())
    return new_args

