def next_version(version):
        """Next version identifier following existing pattern.

        Must deal with both zero-prefixed and non-zero prefixed versions.
        """
        m = re.match(r"([0-9]+)\.([0-9]+)", version)
        if not m:
            raise ValueError("Invalid version number format: " + version)

        major, minor = int(m.group(1)), int(m.group(2))
        if minor == 9:
            return f"{major + 1}.0"
        else:
            return f"{major}.{minor + 1}"

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    # If the version is a string, it is assumed to be a non-zero-prefixed version (e.g., "1.0.0")
    if isinstance(version, str):
        # Split the version into its major, minor, and patch components and convert them to integers
        major, minor, patch = map(int, version.split("."))
        # If the patch version is greater than 1, increment only the patch version and return the result
        if patch > 1:
            return ".".join(str(x) for x in (major, minor, patch + 1))
        # If the minor version is greater than 1, increment only the minor version and return the result
        if minor > 1:
            return ".".join(str(x) for x in (major, minor + 1, 0))
        # Otherwise, increment the major version, set the minor and patch versions to 0, and return the result
        return ".".join(str(x) for x in (major + 1, 0, 0))
    # If the version is an integer, it is assumed to be a zero-prefixed version (e.g., 100000, 2000000)
    else:
        # If the version is greater than 1, increment only the version and return the result
        if version > 1:
            return version + 1
        # Otherwise, return the result of multiplying the version by 10000 and adding 1
        return (version * 10000) + 1

