    for path in find_paths:
        if re.match('^[a-zA-Z]:\\\\', path.lower()):
            # Path is a file or directory, transform to glob pattern
            root, sep, tail = path.rpartition('\\')
            glob_pattern = root.replace('\\', '**/*') + '*/**' + sep + tail
