    command = [commands, *args]
    process_kwargs = {}
    if cwd is not None:
        process_kwargs["cwd"] = cwd
    if env is not None:
        process_kwargs["env"] = env
    with subprocess.Popen(command, stderr=subprocess.PIPE if hide_stderr else None, stdout=subprocess.PIPE, **process_kwargs) as process:
        try:
            output = process.communicate(timeout=None)[0].decode().strip()  #pylint: disable=consider-using-with
