    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """

    plugin_spec_file = os.path.join(plugin_dir, 'plugin.json')  # assume plugin.json is in the plugin's directory
    with open(plugin_spec_file, 'r') as f:
        plugin_spec = json.load(f)  # load the json file into a dictionary

    flat_dict = {}
    for key, value in plugin_spec.items():
        if isinstance(value, dict):
            for sub_key, sub_value in value.items():
                key_with_subkey = '{}_{}'.format(key, sub_key)
                flat_dict[key_with_subkey] = sub_value
        else:
            flat_dict[key] = value

    return flat_dict

